SourceCode.Declaration:
[DataContractAttribute]
class TFMDrawFlowLogicBlockDataContract
{
    Name        blockName;
    ClassName   className;
    Name        editorName;

}

Method.Source:
[DataMemberAttribute('blockName')]
public Name parmBlockName(Name _blockName = blockName)
{
    blockName = _blockName;
    return blockName;
}

[DataMemberAttribute('className')]
public str parmClassName(ClassName _className = className)
{
    className = _className;
    return className;
}

[DataMemberAttribute('editorName')]
public str parmEditorName(ClassName _editorName = editorName)
{
    editorName = _editorName;
    return editorName;
}

public static TFMDrawFlowLogicBlockDataContract Construct(Name _blockName, ClassName _className)
{
    TFMDrawFlowLogicBlockDataContract dataContract = new TFMDrawFlowLogicBlockDataContract();
    dataContract.parmBlockName(_blockName);
    dataContract.parmClassName(_className);
    dataContract.parmEditorName('editornameplaceholder');

    return dataContract;
}
